mapper.select:
SELECT KINDERGARTEN_ID, NUM, TITLE, CONTENT, AUTHOR, CONTENT, PINNED, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT, UNIX_TIMESTAMP(UPDATED_AT) * 1000 UPDATED_AT, COALESCE(
    (SELECT NICKNAME FROM T_RELATIONSHIP R WHERE R.KINDERGARTEN_ID = #{kindergartenId} AND AUTHOR = R.USER_ID),
    (SELECT NAME FROM T_USER U WHERE U.ID = AUTHOR)
) AUTHOR_NAME
FROM T_NOTICE
WHERE KINDERGARTEN_ID = #{kindergartenId} AND NUM = #{num}

mapper.update:
UPDATE T_NOTICE
SET TITLE = #{title}, PINNED = #{pinned}, CONTENT = #{content}
WHERE KINDERGARTEN_ID = #{kindergartenId} AND NUM = #{num}
